/**
 * `runAction` (ADR 0092 §1): the one entry every reader calls — the routes as
 * `web`, the MCP server as `mcp`, a later in-app agent as `agent`.
 *
 * In order, and the same for every reader:
 *
 * 1. **Caller.** An action runs only for the callers it lists. A model that
 *    reaches one of the athlete's own yeses is refused `needs-athlete-yes`,
 *    with the link to where the athlete answers (ADR 0093 §3); any other
 *    caller outside the list is `not-allowed`.
 * 2. **Scope.** A credential that carries scopes must carry the kind's
 *    (`needs-scope`). The MCP reader answers `403 insufficient_scope` before
 *    it gets here; this is the same rule for every other reader.
 * 3. **Input,** validated once against the action's `zod/v4` schema
 *    (`invalid-input`). Readers do not validate it again.
 * 4. **Run,** with the provenance gate's credit sink. A refusal is returned,
 *    never thrown. Anything thrown is `not-run` for a read (nothing was
 *    written) and `unknown` for a write (it may have committed: read first).
 *
 * It never throws, except for a name no action has, which is a programming
 * error rather than an outcome.
 */

import * as Sentry from '@sentry/react-router'
import { SOURCE_ATTRIBUTION_LABELS } from '#app/utils/labels.ts'
import { ATTRIBUTIONS } from '#app/utils/source-terms.ts'
import { type ActionCtx, type AnyActionResult, type RunCtx } from './define.ts'
import { type Credit } from './reading.ts'
import { ATHLETE_YES_PATH } from './paths.ts'
import { Refusal, nextOf, refuse } from './refusals.ts'
import { type ActionName, getAction, type ResultOf } from './registry.server.ts'
import { isModelCaller, SCOPE_OF_KIND } from './vocabulary.ts'

export async function runAction<N extends ActionName>(
	ctx: ActionCtx,
	name: N,
	rawInput: unknown,
): Promise<ResultOf<N>> {
	return (await run(ctx, name, rawInput)) as ResultOf<N>
}

async function run(
	ctx: ActionCtx,
	name: ActionName,
	rawInput: unknown,
): Promise<AnyActionResult> {
	const action = getAction(name)
	const link = (path: string) => new URL(path, ctx.origin).toString()

	if (!action.callers.includes(ctx.caller)) {
		const answersForTheAthlete =
			isModelCaller(ctx.caller) && action.callers.includes('web')
		return refused(
			answersForTheAthlete
				? refuse('needs-athlete-yes', { link: link(ATHLETE_YES_PATH) })
				: refuse('not-allowed'),
		)
	}
	if (ctx.scopes && !ctx.scopes.includes(SCOPE_OF_KIND[action.kind])) {
		return refused(refuse('needs-scope'))
	}

	const parsed = action.input.safeParse(rawInput ?? {})
	if (!parsed.success) return refused(refuse('invalid-input'))

	// One of each line, however many values owe it.
	const owed = new Map<string, Credit>()
	const runCtx: RunCtx = {
		...ctx,
		credit: (credit) => owed.set(`${credit.platform}\0${credit.text}`, credit),
		link,
	}
	try {
		const value: unknown = await action.run(runCtx, parsed.data)
		if (value instanceof Refusal) return refused(value)
		return {
			outcome: 'done',
			value,
			credits: [...owed.values()].sort(byCreditOrder),
		}
	} catch (error) {
		console.error(`[actions] ${name} failed`, error)
		// The envelope says only `not-run` or `unknown`, so the error itself
		// reaches Sentry here or nowhere.
		Sentry.captureException(error)
		return action.kind === 'read'
			? { outcome: 'not-run', reason: 'internal' }
			: {
					outcome: 'unknown',
					message:
						'The action failed after it started and may have changed something. Read before retrying.',
				}
	}
}

/**
 * Credits in the platforms' fixed order, and within a platform the recording's
 * line before the derived one, so a result reads the same each time.
 */
function byCreditOrder(a: Credit, b: Credit): number {
	const derived = (c: Credit) =>
		c.text === SOURCE_ATTRIBUTION_LABELS.derived[c.platform] ? 1 : 0
	return (
		ATTRIBUTIONS.indexOf(a.platform) - ATTRIBUTIONS.indexOf(b.platform) ||
		derived(a) - derived(b)
	)
}

function refused(refusal: Refusal): AnyActionResult {
	return {
		outcome: 'refused',
		code: refusal.code,
		next: nextOf(refusal.code),
		message: refusal.message,
		...(refusal.link ? { link: refusal.link } : {}),
	}
}

/**
 * The **SessionSummary** every session-shaped read returns (ADR 0092, "The
 * first slice"): one planned or recorded session as a model may see it, with
 * every number a Reading through the provenance gate.
 *
 * Built on the same derivations the screens use — `deriveLedgerStatus`,
 * `sessionOwner`, and `buildReviewComparison` for planned against actual — so
 * a session reads the same to a model as on I dag.
 */

import { z } from 'zod/v4'
import {
	originPlatformOf,
	type OriginPlatform,
} from '#app/integrations/shared/origin-platform.ts'
import { localDate } from '#app/utils/athlete-calendar.ts'
import { prisma } from '#app/utils/db.server.ts'
import { nbDisciplineLabel } from '#app/utils/labels.ts'
import { type PlannedMetric } from '#app/utils/planned-discipline.ts'
import { SESSION_OWNERS, sessionOwner } from '#app/utils/session-ownership.ts'
import { type DisciplineThresholdMap } from '#app/utils/intensity-target.ts'
import { buildReviewComparison } from '#app/utils/session-review.ts'
import {
	getDisciplineThresholds,
	type LedgerSession,
} from '#app/utils/training.server.ts'
import {
	deriveLedgerStatus,
	getSessionDiscipline,
} from '#app/utils/training.ts'
import { type RunCtx } from './define.ts'
import { sessionPath } from './paths.ts'
import {
	athleteText,
	AthleteTextSchema,
	gate,
	NumberReading,
	reading,
	type Reading,
	type ReadingContext,
	unavailable,
} from './reading.ts'

export const SESSION_STATUSES = [
	'planned',
	'done',
	'missed',
	'recording-only',
] as const

/** A workout title the athlete wrote stays theirs, capped like a name. */
const TITLE_MAX = 200

export const SessionSummarySchema = z.object({
	id: z.string(),
	/** `YYYY-MM-DD` in the Athlete Timezone. */
	date: z.string(),
	discipline: z.string(),
	/**
	 * A stored title, as the athlete's text; the discipline in trainm8's
	 * words when there is none, or when a detected title's terms close it.
	 */
	title: z.union([AthleteTextSchema, z.string()]),
	status: z.enum(SESSION_STATUSES),
	/** **Session Ownership**: whose session it is to change. */
	owner: z.enum(SESSION_OWNERS),
	planned: z.object({
		durationS: NumberReading(),
		distanceM: NumberReading(),
		tss: NumberReading(),
	}),
	actual: z.object({
		durationS: NumberReading(),
		distanceM: NumberReading(),
		tss: NumberReading(),
	}),
	/** A deep link to the session in trainm8. */
	link: z.string(),
})
export type SessionSummary = z.infer<typeof SessionSummarySchema>

/**
 * The Origin Platforms behind each session's Recording, aliases included
 * (ADR 0096 §3, ADR 0098 §1), for the sessions given. One query. A session
 * with no Recording is absent: its actuals bind to nothing recorded.
 */
export async function readRecordingBindingSets(
	userId: string,
	sessionIds: readonly string[],
): Promise<Map<string, OriginPlatform[]>> {
	if (sessionIds.length === 0) return new Map()
	const rows = await prisma.workoutSession.findMany({
		where: { userId, id: { in: [...sessionIds] }, recordingId: { not: null } },
		select: {
			id: true,
			recording: {
				select: {
					originPlatform: true,
					aliases: { select: { originPlatform: true } },
				},
			},
		},
	})
	return new Map(
		rows.flatMap((row) =>
			row.recording
				? [
						[
							row.id,
							[
								...new Set([
									originPlatformOf(row.recording.originPlatform),
									...row.recording.aliases.map((alias) =>
										originPlatformOf(alias.originPlatform),
									),
								]),
							],
						],
					]
				: [],
		),
	)
}

/**
 * The binding set of a session's Workout (ADR 0098 §1), the one answer every
 * read asks before it states anything of the prescription. An independent
 * prescription (authored, generated) binds to nothing. A Workout detected
 * from the session's Recording (`materializeDetectedStructure`) is that
 * Recording's data — its title, repeats, durations and intensities were
 * measured — so it binds to the Recording's set, adopted or not: adopting it
 * keeps the measured figures the athlete did not change.
 */
export function workoutBindingSet(
	session: { source: string },
	recordingBindingSet: readonly OriginPlatform[],
): readonly OriginPlatform[] {
	return session.source === 'detected' ? recordingBindingSet : []
}

/**
 * A planned figure, as a Reading. It binds to `bindingSet`, the Workout's
 * ({@link workoutBindingSet}): nothing for an independent prescription.
 */
export function plannedReading(
	metric: PlannedMetric<number>,
	ctx: ReadingContext,
	{
		zeroIsUnresolved = false,
		bindingSet = [],
	}: {
		zeroIsUnresolved?: boolean
		bindingSet?: readonly OriginPlatform[]
	} = {},
): Reading<number> {
	if (metric.status === 'unavailable') {
		return reading(unavailable(metric.reason), bindingSet, ctx)
	}
	// A Planned TSS of zero is one that did not resolve (`week-volumes.ts`
	// reads it the same way), so it is never sent as a zero.
	return zeroIsUnresolved && metric.value <= 0
		? reading(unavailable('not-resolved'), bindingSet, ctx)
		: reading(metric.value, bindingSet, ctx)
}

export function sessionStatus(
	session: Pick<LedgerSession, 'status' | 'scheduledAt' | 'workout'>,
	now: Date,
	timezone: string,
): SessionSummary['status'] {
	if (session.workout == null) return 'recording-only'
	const status = deriveLedgerStatus(session, now, timezone)
	return status === 'completed' ? 'done' : status
}

export function sessionTitle(
	session: Pick<
		LedgerSession,
		'source' | 'adoptedAt' | 'workout' | 'recording'
	>,
	/** The Workout's binding set ({@link workoutBindingSet}). */
	bindingSet: readonly OriginPlatform[],
	ctx: ReadingContext,
): SessionSummary['title'] {
	const { workout } = session
	const disciplineLabel = () => nbDisciplineLabel(getSessionDiscipline(session))
	if (!workout) return disciplineLabel()
	// A detected title is made of the measurements ("4 × 6 min"): it passes
	// the gate like any of them, and where the terms close it the discipline
	// stands in.
	if (session.source === 'detected' && gate(bindingSet, ctx)) {
		return disciplineLabel()
	}
	// Ownership does not say who wrote the title: a title-only edit leaves a
	// machine's session unadopted. So every stored title crosses as the
	// athlete's, marked and capped — the safe side of not knowing.
	return athleteText(workout.title, TITLE_MAX)
}

/**
 * One ledger row as a SessionSummary. `bindingSet` is the session's
 * Recording's platforms (from {@link readRecordingBindingSets}); its actuals
 * pass the gate with it, so a Strava-recorded run's numbers never reach a
 * model while its plan still does.
 */
export function toSessionSummary(
	session: LedgerSession,
	bindingSet: readonly OriginPlatform[],
	/** What a distance step's pace resolves against (#615). */
	thresholds: DisciplineThresholdMap,
	ctx: RunCtx,
): SessionSummary {
	const status = sessionStatus(session, ctx.now, ctx.timezone)
	const review = buildReviewComparison(session, thresholds)
	const prescribed = workoutBindingSet(session, bindingSet)
	const { recording } = session
	const missing = recording ? 'not-resolved' : 'no-recording'
	// The Recording's own figures: they owe its source line, not the derived one.
	const recorded = (value: number | null | undefined) =>
		reading(value ?? unavailable(missing), bindingSet, ctx, {
			origin: 'recording',
		})
	return {
		id: session.id,
		date: localDate(session.scheduledAt, ctx.timezone),
		discipline: getSessionDiscipline(session),
		title: sessionTitle(session, prescribed, ctx),
		status,
		owner: sessionOwner(session),
		planned: {
			durationS: plannedReading(review.duration.plannedRead, ctx, {
				bindingSet: prescribed,
			}),
			distanceM: plannedReading(review.distance.plannedRead, ctx, {
				bindingSet: prescribed,
			}),
			tss: plannedReading(review.tss.plannedRead, ctx, {
				zeroIsUnresolved: true,
				bindingSet: prescribed,
			}),
		},
		actual: {
			durationS: recorded(recording?.durationSec),
			distanceM: recorded(recording?.distanceM),
			// TSS may come from the athlete's RPE with no Recording at all; then
			// it is athlete-entered and binds to nothing recorded.
			tss: reading(
				session.tssValue ??
					unavailable(
						recording || status === 'done' ? 'not-resolved' : 'no-recording',
					),
				recording ? bindingSet : [],
				ctx,
			),
		},
		link: ctx.link(sessionPath(session.id)),
	}
}

/** Many ledger rows as SessionSummaries, with their binding sets in one query. */
export async function toSessionSummaries(
	sessions: readonly LedgerSession[],
	ctx: RunCtx,
): Promise<SessionSummary[]> {
	const [bindingSets, thresholds] = await Promise.all([
		readRecordingBindingSets(
			ctx.userId,
			sessions.map((s) => s.id),
		),
		getDisciplineThresholds(ctx.userId),
	])
	return sessions.map((session) =>
		toSessionSummary(
			session,
			bindingSets.get(session.id) ?? [],
			thresholds,
			ctx,
		),
	)
}

/**
 * DEV ONLY — the floating athlete switcher.
 *
 * Rendered by the root route, but only when the root loader hands down
 * `devAthletes`, which it only queries when `NODE_ENV === 'development'`. In
 * production the prop is `null` and this component never mounts.
 *
 * Deliberately dev chrome, not product UI: bottom-LEFT (bottom-centre belongs to
 * the plan prototype switcher), high contrast, tiny, numbers only.
 */
import { useCallback, useEffect, useState } from 'react'
import { useFetcher, useLocation } from 'react-router'
import { type DevAthlete } from '#app/utils/dev-athletes.server.ts'
import { cn } from '#app/utils/misc.tsx'

const STORAGE_KEY = 'dev-athlete-switcher-open'

export function DevAthleteSwitcher({
	athletes,
	username,
}: {
	athletes: Array<DevAthlete>
	username: string | null
}) {
	const [open, setOpen] = useState(false)
	const location = useLocation()
	const fetcher = useFetcher()
	const returnTo = `${location.pathname}${location.search}`

	// Read after hydration: the server can't know localStorage.
	useEffect(() => {
		setOpen(localStorage.getItem(STORAGE_KEY) === '1')
	}, [])

	const toggle = useCallback(() => {
		setOpen((wasOpen) => {
			const next = !wasOpen
			localStorage.setItem(STORAGE_KEY, next ? '1' : '0')
			return next
		})
	}, [])

	// Ctrl+Alt+D toggles. `code` not `key`, because Alt+d on macOS types "∂".
	useEffect(() => {
		function onKeyDown(event: KeyboardEvent) {
			if (event.code !== 'KeyD' || !event.ctrlKey || !event.altKey) return
			const target = event.target
			if (target instanceof HTMLElement) {
				if (
					target.isContentEditable ||
					['INPUT', 'TEXTAREA', 'SELECT'].includes(target.tagName)
				) {
					return
				}
			}
			event.preventDefault()
			toggle()
		}
		document.addEventListener('keydown', onKeyDown)
		return () => document.removeEventListener('keydown', onKeyDown)
	}, [toggle])

	const busy = fetcher.state !== 'idle'

	return (
		// Above the phone's tab bar (ADR 0083), so it never covers a tab.
		<div className="fixed bottom-[calc(var(--tab-bar-space)+0.75rem)] left-3 z-50 flex flex-col items-start gap-1 text-xs">
			{open ? (
				<div className="bg-background max-w-[15rem] rounded-md border-2 border-amber-500 shadow-lg">
					<div className="flex items-center justify-between gap-2 border-b px-2 py-1 text-amber-600 dark:text-amber-400">
						<span className="font-mono">dev</span>
						<span className="text-muted-foreground tabular-nums">
							km/wk · s/wk
						</span>
					</div>
					<ul>
						{athletes.map((athlete) => (
							<li key={athlete.username}>
								<button
									type="button"
									disabled={!athlete.seeded || busy}
									aria-current={
										athlete.username === username ? 'true' : undefined
									}
									onClick={() =>
										fetcher.submit(
											{ username: athlete.username, returnTo },
											{
												method: 'POST',
												action: '/resources/dev-switch-athlete',
											},
										)
									}
									className={cn(
										'hover:bg-muted flex w-full items-baseline gap-2 px-2 py-1.5 text-left disabled:opacity-50',
										athlete.username === username && 'bg-muted font-semibold',
									)}
								>
									<span className="w-10 shrink-0 truncate font-mono">
										{athlete.username}
									</span>
									<span className="text-muted-foreground min-w-0 flex-1 truncate">
										{athlete.seeded ? athlete.level : 'not seeded'}
									</span>
									{athlete.seeded ? (
										<span className="shrink-0 tabular-nums">
											{athlete.kmPerWeek.toFixed(0)} · {athlete.sessionsPerWeek}
										</span>
									) : null}
								</button>
							</li>
						))}
						<li>
							<fetcher.Form method="POST" action="/logout">
								<button
									type="submit"
									disabled={busy || !username}
									className="hover:bg-muted w-full border-t px-2 py-1.5 text-left disabled:opacity-50"
								>
									Log out
								</button>
							</fetcher.Form>
						</li>
					</ul>
				</div>
			) : null}
			<button
				type="button"
				onClick={toggle}
				title="Dev athlete switcher (Ctrl+Alt+D)"
				aria-expanded={open}
				className="bg-background rounded-full border-2 border-amber-500 px-2 py-0.5 font-mono shadow-lg"
			>
				{username ?? 'nobody'}
			</button>
		</div>
	)
}

import { type ComponentProps } from 'react'

import { cn } from '#app/utils/misc.tsx'

export function FloatingToolbar({
	className,
	...props
}: ComponentProps<'div'>) {
	return (
		<div
			className={cn(
				'bg-muted/80 shadow-accent absolute inset-x-3 bottom-3 flex items-center justify-end gap-2 rounded-lg p-4 pl-5 shadow-xl backdrop-blur-xs md:gap-4 md:pl-7',
				className,
			)}
			{...props}
		/>
	)
}

import fs from 'node:fs'
import path from 'node:path'
import { expect, test } from 'vitest'
import { getSessionExpirationDate } from '#app/utils/auth.server.ts'
import { getToast } from '#app/utils/toast.server.ts'
import { prisma } from '#app/utils/db.server.ts'
import { createUser, createPassword } from '#tests/db-utils.ts'
import { BASE_URL, getSessionCookieHeader } from '#tests/utils.ts'
import { action } from './imports.share-target.tsx'

const FIT_FIXTURES = path.join(process.cwd(), 'tests', 'fixtures', 'fit')

async function setupAthlete() {
	const userData = createUser()
	const user = await prisma.user.create({
		select: { id: true },
		data: {
			...userData,
			password: { create: createPassword(userData.username) },
		},
	})
	const session = await prisma.session.create({
		select: { id: true },
		data: { userId: user.id, expirationDate: getSessionExpirationDate() },
	})
	const cookieHeader = await getSessionCookieHeader(session)
	return { userId: user.id, cookieHeader }
}

function fitFile(name: string) {
	const bytes = fs.readFileSync(path.join(FIT_FIXTURES, name))
	return new File([new Uint8Array(bytes)], name, {
		type: 'application/octet-stream',
	})
}

function gpxFile(name = 'shared-run.gpx') {
	const content = `<?xml version="1.0" encoding="UTF-8"?>
<gpx version="1.1" creator="test">
	<trk>
		<type>running</type>
		<trkseg>
			<trkpt lat="59.9100" lon="10.7400"><time>2026-06-02T07:30:00Z</time></trkpt>
			<trkpt lat="59.9200" lon="10.7400"><time>2026-06-02T07:45:00Z</time></trkpt>
			<trkpt lat="59.9300" lon="10.7400"><time>2026-06-02T08:00:00Z</time></trkpt>
		</trkseg>
	</trk>
</gpx>`
	return new File([content], name, { type: 'application/gpx+xml' })
}

async function shareFiles(cookieHeader: string, files: File[]) {
	const formData = new FormData()
	for (const file of files) formData.append('file', file)
	const request = new Request(`${BASE_URL}/imports/share-target`, {
		method: 'POST',
		headers: { cookie: cookieHeader },
		body: formData,
	})
	return action({ request, params: {}, context: {} } as any)
}

function expectRedirect(result: unknown, location: string) {
	if (!(result instanceof Response)) {
		throw new Error('Expected a redirect Response')
	}
	expect(result.status).toBe(303)
	expect(result.headers.get('location')).toBe(location)
}

test('a shared GPX file auto-saves onto The Tape via the shared ingest path', async () => {
	const { userId, cookieHeader } = await setupAthlete()

	const result = await shareFiles(cookieHeader, [gpxFile()])
	expectRedirect(result, '/')

	const imports = await prisma.activityImport.findMany({
		where: { athleteId: userId },
	})
	expect(imports).toHaveLength(1)
	expect(imports[0]!.externalProvider).toBe('manual')
	expect(imports[0]!.discipline).toBe('run')
})

test('a shared FIT file imports with device metrics', async () => {
	const { userId, cookieHeader } = await setupAthlete()

	const result = await shareFiles(cookieHeader, [fitFile('run-with-hr.fit')])
	expectRedirect(result, '/')

	const imports = await prisma.activityImport.findMany({
		where: { athleteId: userId },
	})
	expect(imports).toHaveLength(1)
	expect(imports[0]!.discipline).toBe('run')
	expect(imports[0]!.hrAvg).not.toBeNull()
})

test('sharing the same file twice dedupes by content hash', async () => {
	const { userId, cookieHeader } = await setupAthlete()

	await shareFiles(cookieHeader, [fitFile('run-with-hr.fit')])
	const result = await shareFiles(cookieHeader, [fitFile('run-with-hr.fit')])
	expectRedirect(result, '/')

	const count = await prisma.activityImport.count({
		where: { athleteId: userId },
	})
	expect(count).toBe(1)
})

/** The toast a redirect carries, read back as the next page would read it. */
async function toastOf(result: unknown) {
	if (!(result instanceof Response)) throw new Error('Expected a Response')
	const cookie = result.headers.get('set-cookie')?.split(';')[0] ?? ''
	const { toast } = await getToast(
		new Request(BASE_URL, { headers: { cookie } }),
	)
	return toast
}

test('a shared file that lands says so in Norwegian on I dag', async () => {
	const { cookieHeader } = await setupAthlete()

	const result = await shareFiles(cookieHeader, [gpxFile()])

	expectRedirect(result, '/')
	expect(await toastOf(result)).toMatchObject({
		title: '1 økt importert',
		type: 'success',
	})
})

test('a shared file that cannot be read says what failed instead of dropping it', async () => {
	const { userId, cookieHeader } = await setupAthlete()
	const broken = new File(['not a gpx at all'], 'broken.gpx', {
		type: 'application/gpx+xml',
	})

	const result = await shareFiles(cookieHeader, [broken])

	expectRedirect(result, '/')
	expect(await toastOf(result)).toMatchObject({
		title: 'Ingen økter ble importert',
		description: '1 fil kunne ikke leses: broken.gpx (Ikke en gyldig GPX-fil)',
		type: 'error',
	})
	expect(
		await prisma.activityImport.count({ where: { athleteId: userId } }),
	).toBe(0)
})

test('sharing a file twice says it was there already', async () => {
	const { cookieHeader } = await setupAthlete()

	await shareFiles(cookieHeader, [fitFile('run-with-hr.fit')])
	const result = await shareFiles(cookieHeader, [fitFile('run-with-hr.fit')])

	expect(await toastOf(result)).toMatchObject({
		title: 'Ingen økter ble importert',
		description: '1 fantes fra før.',
		type: 'message',
	})
})

test('sharing no files redirects to the upload page instead of erroring', async () => {
	const { cookieHeader } = await setupAthlete()

	const result = await shareFiles(cookieHeader, [])
	expectRedirect(result, '/imports/upload')
})

// ── Athlete Timezone day attribution (#173) ────────────────────────────────

/** A GPX run at 22:30–23:00 UTC on May 31 — 00:30–01:00 June 1 in Europe/Oslo. */
function lateNightGpx(name = 'late-night-run.gpx') {
	const content = `<?xml version="1.0" encoding="UTF-8"?>
<gpx version="1.1" creator="test">
	<trk>
		<type>running</type>
		<trkseg>
			<trkpt lat="59.9100" lon="10.7400"><time>2026-05-31T22:30:00Z</time></trkpt>
			<trkpt lat="59.9200" lon="10.7400"><time>2026-05-31T22:45:00Z</time></trkpt>
			<trkpt lat="59.9300" lon="10.7400"><time>2026-05-31T23:00:00Z</time></trkpt>
		</trkseg>
	</trk>
</gpx>`
	return new File([content], name, { type: 'application/gpx+xml' })
}

async function createPlannedRun(userId: string, scheduledAt: Date) {
	const workout = await prisma.workout.create({
		select: { id: true },
		data: {
			title: 'Easy run',
			discipline: 'run',
			intent: 'endurance',
			ownerId: userId,
			blocks: {
				create: [
					{
						orderIndex: 0,
						steps: {
							create: [
								{
									notes: '30 min easy',
									discipline: 'run',
									intensity: 'easy',
									orderIndex: 0,
								},
							],
						},
					},
				],
			},
		},
	})
	return prisma.workoutSession.create({
		select: { id: true },
		data: { userId, workoutId: workout.id, scheduledAt, status: 'planned' },
	})
}

test('a share near local midnight auto-matches the planned session on the Oslo day', async () => {
	const { userId, cookieHeader } = await setupAthlete()
	await prisma.athleteProfile.create({
		data: { userId, timezone: 'Europe/Oslo' },
	})
	// The 22:30Z activity is 00:30 June 1 in Oslo; a hardcoded-UTC share-target
	// would file it under May 31 and never match this June 1 session.
	const planned = await createPlannedRun(
		userId,
		new Date('2026-06-01T06:00:00Z'),
	)

	const result = await shareFiles(cookieHeader, [lateNightGpx()])
	expectRedirect(result, '/')

	const imported = await prisma.activityImport.findFirstOrThrow({
		where: { athleteId: userId },
	})
	expect(imported.promotedSessionId).toBe(planned.id)
})

test('without an Athlete Profile the share day attribution degrades to UTC', async () => {
	const { userId, cookieHeader } = await setupAthlete()
	const planned = await createPlannedRun(
		userId,
		new Date('2026-06-01T06:00:00Z'),
	)

	await shareFiles(cookieHeader, [lateNightGpx()])

	// It auto-saves either way (ADR 0049) — the point is that it did *not* match
	// the June 1 plan, so it stands up a recording-only session of its own.
	const imported = await prisma.activityImport.findFirstOrThrow({
		where: { athleteId: userId },
	})
	expect(imported.promotedSessionId).not.toBe(planned.id)
	const session = await prisma.workoutSession.findUniqueOrThrow({
		where: { id: planned.id },
	})
	expect(session.recordingId).toBeNull()
})

