import { type AppLoadContext } from 'react-router'
import { expect, test } from 'vitest'
import { getSessionExpirationDate } from '#app/utils/auth.server.ts'
import { prisma } from '#app/utils/db.server.ts'
import {
	guardedRoundFactor,
	ROUND_STEP_UP,
} from '#app/utils/load/propose-next-round.ts'
import { PLAN_READY_LABELS } from '#app/utils/labels.ts'
import { appendOpenEndedRound } from '#app/utils/plan-outline/open-ended.server.ts'
import { getSeasonForOutline } from '#app/utils/training.server.ts'
import { createPassword, createUser } from '#tests/db-utils.ts'
import { BASE_URL, getSessionCookieHeader } from '#tests/utils.ts'
import { loader } from './klar.tsx'
import { action as choose } from './valg.tsx'

// _Planen er klar_ (#570) through its loader, after _Velg denne_ made the
// plan: the plain name, the day it begins, the 12-week curve of hours (the
// round as laid, then the two rounds the autopilot would append if every week
// were done to plan), the Sunday sentence and _Under panseret_.

const ARGS = {
	params: {},
	context: {} as AppLoadContext,
	unstable_pattern: '/start/klar',
}

async function setUp() {
	const userData = createUser()
	const session = await prisma.session.create({
		data: {
			expirationDate: getSessionExpirationDate(),
			user: {
				create: {
					...userData,
					password: { create: createPassword(userData.username) },
				},
			},
		},
		select: { id: true, userId: true },
	})
	return {
		userId: session.userId,
		cookie: await getSessionCookieHeader(session),
	}
}

function get(path: string, cookie: string) {
	return new Request(new URL(path, BASE_URL).toString(), {
		headers: { cookie },
	})
}

function post(path: string, entries: Array<[string, string]>, cookie: string) {
	return new Request(new URL(path, BASE_URL).toString(), {
		method: 'POST',
		headers: { cookie, 'content-type': 'application/x-www-form-urlencoded' },
		body: new URLSearchParams(entries).toString(),
	})
}

async function settle<T>(run: () => Promise<T>): Promise<T | Response> {
	try {
		return await run()
	} catch (thrown) {
		if (thrown instanceof Response) return thrown
		throw thrown
	}
}

function location(response: unknown): string | null {
	const raw =
		response instanceof Response ? response.headers.get('location') : null
	return raw == null ? null : decodeURIComponent(raw)
}

/** A beginner's three hours of running on Monday, Wednesday and Friday. */
function choice(family: string): Array<[string, string]> {
	return [
		['level', 'beginner'],
		['hours', '3'],
		['discipline', 'run'],
		['days', '0'],
		['days', '2'],
		['days', '4'],
		['family', family],
	]
}

async function pick(family: string, cookie: string) {
	return settle(() =>
		choose({
			request: post('/start/valg', choice(family), cookie),
			...ARGS,
			unstable_pattern: '/start/valg',
		}),
	)
}

/** Each week's hours across the plan's tracks, as Sesong reads them. */
async function seasonHours(userId: string, outlineId: string) {
	const season = await getSeasonForOutline(userId, outlineId)
	return season!.weeks.map((week) =>
		week.targets.reduce((sum, target) => sum + (target.value ?? 0), 0),
	)
}

test('Velg denne takes the athlete to Planen er klar: the plain name, the family small and the day the plan begins', async () => {
	const { cookie } = await setUp()
	expect(location(await pick('big-base', cookie))).toBe('/start/klar')

	const ready = await loader({ request: get('/start/klar', cookie), ...ARGS })
	expect(ready.overline).toBe('Planen er klar')
	expect(ready.name).toBe('Bygg grunnform først')
	expect(ready.familyName).toBe('Fagnavn: Stor base')
	expect(ready.startsOn).toMatch(
		/^Planen starter mandag \d{1,2}\. (januar|februar|mars|april|mai|juni|juli|august|september|oktober|november|desember)\.$/,
	)
	expect(ready.toToday).toBe('/')
})

test('the curve is 12 weeks of hours: the round as laid from the hours given, and two rounds dashed, as the autopilot would append them if every week were done to plan', async () => {
	const { userId, cookie } = await setUp()
	await pick('classic', cookie)
	const ready = await loader({ request: get('/start/klar', cookie), ...ARGS })
	const outline = await prisma.planOutline.findFirstOrThrow({
		where: { athleteId: userId },
		select: { id: true, startWeekKey: true },
	})

	const drawn = ready.curve.points.map((point) => point.target)
	expect(drawn).toHaveLength(12)
	// Week 1 is the hours given (ADR 0091 §3); the round as laid is the plan's
	// own derivation, week for week.
	expect(drawn[0]).toBe(3)
	expect(drawn.slice(0, 4)).toEqual(await seasonHours(userId, outline.id))
	expect(ready.curve.projectedFrom).toBe(4)
	expect(ready.curve.points[0]!.key).toBe(outline.startWeekKey)

	// What the autopilot would append for two rounds done to plan: +5 % each,
	// capped so the round's ramp × the step stays inside the 8 % guard. Append
	// them for real at that factor, and the season reads what was drawn dashed.
	const segments = await prisma.trainingTrackSegment.findMany({
		where: {
			phase: { outlineId: outline.id },
			kind: 'endurance',
			track: { discipline: { not: 'other' } },
		},
		select: { ramp: true },
	})
	const ramps = segments.flatMap((segment) =>
		segment.ramp == null ? [] : [segment.ramp],
	)
	const ramp = ramps.length > 0 ? Math.max(...ramps) : null
	const factor = guardedRoundFactor(ROUND_STEP_UP, ramp)
	// A beginner's 5 % ramp leaves room for 2.85 %, not 5 %.
	expect(factor).toBeLessThan(ROUND_STEP_UP)
	expect((1 + (ramp ?? 0)) * factor).toBeLessThanOrEqual(1.08 + 1e-9)
	for (const round of [2, 3]) {
		const phases = await prisma.planOutlinePhase.findMany({
			where: { outlineId: outline.id },
			orderBy: { orderIndex: 'desc' },
			select: { id: true },
		})
		await prisma.$transaction((tx) =>
			appendOpenEndedRound(
				tx,
				userId,
				{
					kind: 'add-phase',
					outlineId: outline.id,
					afterPhaseId: phases[0]!.id,
					name: `Blokk ${round}`,
					weeks: 4,
					rhythm: '3:1',
					factor,
				},
				{ now: new Date(), timezone: 'UTC' },
			),
		)
	}
	expect(drawn).toEqual(await seasonHours(userId, outline.id))
	// The next round opens higher than the first did.
	expect(drawn[4]!).toBeGreaterThan(drawn[0]!)
	expect(ready.curve.note).toBe(
		PLAN_READY_LABELS.note(Math.round((factor - 1) * 100)),
	)
})

test('Planen er klar says how the plan moves each Sunday, and where to ask the app to check first', async () => {
	const { cookie } = await setUp()
	await pick('polarized', cookie)
	const ready = await loader({ request: get('/start/klar', cookie), ...ARGS })
	expect(ready.sunday).toBe(
		'Hver søndag kveld legger appen ut neste uke, ut fra det du faktisk trente. Du får beskjed om hva den gjorde, og kan angre. Vil du heller at den spør deg først, velger du Spør meg først i Meg.',
	)
})

test('Under panseret reads what was made: the family, open-ended, the rhythm, the track with its starting volume, the Week Pattern and the level', async () => {
	const { cookie } = await setUp()
	await pick('big-base', cookie)
	const { hood } = await loader({
		request: get('/start/klar', cookie),
		...ARGS,
	})
	expect(hood.title).toBe('Under panseret')
	expect(hood.facts).toEqual([
		{ term: 'Filosofi', details: ['Stor base'] },
		{
			term: 'Lengde',
			details: ['Åpen, uten løp og uten sluttdato. Den går blokk for blokk.'],
		},
		{ term: 'Rytme', details: ['3 uker som bygger, så 1 lett'] },
		{ term: 'Spor', details: ['Løping, starter på 3\u00a0t/uke'] },
		{ term: 'Nivå', details: ['Nybegynner'] },
	])
	expect(
		hood.pattern.map((day) => [day.weekday, day.sessions.length > 0]),
	).toEqual([
		['mandag', true],
		['tirsdag', false],
		['onsdag', true],
		['torsdag', false],
		['fredag', true],
		['lørdag', false],
		['søndag', false],
	])
	expect(hood.pattern[0]!.sessions[0]).toMatch(/^Løping · /)
	// The weeks as written: the round laid, its fourth week easy.
	expect(hood.weeks.map((week) => week.easy)).toEqual([
		false,
		false,
		false,
		true,
	])
	expect(hood.weeks[0]!.hours).toBe('3\u00a0t')
})

test('Under panseret also says the strength sessions a week and the Session Preferences the athlete gave', async () => {
	const { cookie } = await setUp()
	await settle(() =>
		choose({
			request: post(
				'/start/valg',
				[
					...choice('big-base'),
					['strength', '2'],
					['preferences', 'long'],
					['preferences', 'short'],
				],
				cookie,
			),
			...ARGS,
			unstable_pattern: '/start/valg',
		}),
	)
	const { hood } = await loader({
		request: get('/start/klar', cookie),
		...ARGS,
	})
	expect(hood.facts.slice(-2)).toEqual([
		{ term: 'Styrke', details: ['2 styrkeøkter i uka'] },
		{
			term: 'Økter du liker',
			details: ['Lange, rolige turer', 'Korte økter'],
		},
	])
})

test('reloading Planen er klar after the plan exists still shows it and never makes a second plan; with no plan it is the start', async () => {
	const { userId, cookie } = await setUp()
	expect(
		location(
			await settle(() =>
				loader({ request: get('/start/klar', cookie), ...ARGS }),
			),
		),
	).toBe('/start/niva')

	await pick('polarized', cookie)
	const first = await loader({ request: get('/start/klar', cookie), ...ARGS })
	const again = await loader({ request: get('/start/klar', cookie), ...ARGS })
	expect(again).toEqual(first)
	// A second Velg denne (a double tap, the back button) makes nothing more.
	await pick('polarized', cookie)
	expect(await prisma.planOutline.count({ where: { athleteId: userId } })).toBe(
		1,
	)
})

import React from 'react'
import { useFetcher } from 'react-router'
import {
	Command,
	CommandEmpty,
	CommandGroup,
	CommandInput,
	CommandItem,
	CommandList,
	CommandSeparator,
} from '#app/components/ui/command.tsx'
import { Button } from '#app/components/ui/button.tsx'
import { Icon } from '#app/components/ui/icon.tsx'
import {
	Popover,
	PopoverContent,
	PopoverTrigger,
} from '#app/components/ui/popover.tsx'
import { Toggle } from '#app/components/ui/toggle.tsx'
import {
	EXERCISE_PICKER_LABELS,
	nbEquipmentLabel,
	nbMuscleLabel,
} from '#app/utils/labels.ts'
import { cn } from '#app/utils/misc.tsx'
import { MUSCLE_GROUPS } from '#app/utils/workout-schema.ts'

const L = EXERCISE_PICKER_LABELS

export type ExerciseItem = {
	id: string
	name: string
	primaryMuscle: string
	equipment: string | null
}

/** A primary muscle's name in the picker (`labels.ts`). */
export function formatMuscleLabel(muscle: string) {
	return nbMuscleLabel(muscle)
}

/**
 * A filter chip: the design system's `Toggle` (`pressable`, an `after:` hit
 * area to ~44px, `aria-pressed`) as a pill. It was a hand-rolled 20px button
 * with `transition-colors` on the browser's curve (#505 round 2).
 */
function FilterChip({
	label,
	pressed,
	onToggle,
}: {
	label: string
	pressed: boolean
	onToggle: () => void
}) {
	return (
		<Toggle
			variant="outline"
			size="sm"
			pressed={pressed}
			onPressedChange={onToggle}
			className="text-caption aria-pressed:border-foreground/20 aria-pressed:text-foreground text-muted-foreground h-7 rounded-full px-2.5 font-normal"
		>
			{label}
		</Toggle>
	)
}

/**
 * The closed picker looks and behaves like the shared select trigger
 * (`components/ui/select.tsx`, deviations D2/D5/D10): a real 44px, 16px text
 * on a phone so iOS never zooms, the luma control radius, and colour on the
 * app's press curve. It was `h-8` with `transition-[color,box-shadow]
 * duration-200` on the built-in curve — the same defect #505 S8 fixed in the
 * select. No scale: it owns a popup (`pressable`'s `aria-haspopup` rule).
 */
const TRIGGER_CLASS =
	// eslint-disable-next-line trainm8/luma-steps -- mirrors the ui/select trigger beside it (`text-base md:text-sm`)
	'bg-input/50 focus-visible:border-ring focus-visible:ring-ring/30 aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40 duration-press flex min-h-11 w-full items-center justify-between gap-1.5 rounded-3xl border border-transparent px-3 py-2 text-base transition-[color,box-shadow,background-color] ease-out outline-none focus-visible:ring-3 disabled:cursor-not-allowed disabled:opacity-50 aria-invalid:ring-3 md:text-sm'

/**
 * Searchable exercise picker for strength steps (ADR 0027 §8, PRD R8):
 * type-ahead over the exercise catalog, filter chips for primary muscle and
 * equipment, a "Recent" group derived by the route loader from the athlete's
 * recent strength steps, and an inline "Create …" row that posts to the
 * existing custom-exercise action and selects the result.
 *
 * Purely presentational with respect to form state: the selected exercise id
 * flows through `value`/`onChange`, which the caller binds to the Conform
 * `exerciseId` field via `useInputControl` — the submitted payload is
 * unchanged from the old flat Select.
 */
export function ExerciseCombobox({
	exercises,
	recentExerciseIds = [],
	value,
	onChange,
	id,
	invalid,
	onFocus,
	onBlur,
}: {
	exercises: ExerciseItem[]
	recentExerciseIds?: string[]
	value: string
	onChange: (exerciseId: string) => void
	id?: string
	invalid?: boolean
	onFocus?: () => void
	onBlur?: () => void
}) {
	const [open, setOpen] = React.useState(false)
	const [query, setQuery] = React.useState('')
	const [muscleFilter, setMuscleFilter] = React.useState<string | null>(null)
	const [equipmentFilter, setEquipmentFilter] = React.useState<string | null>(
		null,
	)
	// Inline create is a two-step flow inside the popover: the "Create …" row
	// captures the typed name, then the list swaps to a primary-muscle picker
	// (the action requires one — never guessed on the athlete's behalf).
	const [createName, setCreateName] = React.useState<string | null>(null)
	// Exercises created inline this visit — appended to the catalog client-side
	// so the new exercise is selectable without a reload.
	const [createdExercises, setCreatedExercises] = React.useState<
		ExerciseItem[]
	>([])
	const createFetcher = useFetcher<{
		exercise?: { id: string; name: string }
		error?: string
	}>()
	const pendingCreateRef = React.useRef<{
		name: string
		primaryMuscle: string
	} | null>(null)
	const onChangeRef = React.useRef(onChange)
	onChangeRef.current = onChange

	const allExercises = React.useMemo(() => {
		const extras = createdExercises.filter(
			(created) => !exercises.some((ex) => ex.id === created.id),
		)
		return [...exercises, ...extras]
	}, [exercises, createdExercises])

	React.useEffect(() => {
		const created = createFetcher.data?.exercise
		const pending = pendingCreateRef.current
		if (!created || !pending) return
		pendingCreateRef.current = null
		setCreatedExercises((prev) =>
			prev.some((ex) => ex.id === created.id)
				? prev
				: [
						...prev,
						{
							id: created.id,
							name: created.name,
							primaryMuscle: pending.primaryMuscle,
							equipment: null,
						},
					],
		)
		onChangeRef.current(created.id)
		setOpen(false)
	}, [createFetcher.data])

	const selected = allExercises.find((ex) => ex.id === value) ?? null

	const muscleOptions = React.useMemo(
		() =>
			[...new Set(allExercises.map((ex) => ex.primaryMuscle))].sort((a, b) =>
				a.localeCompare(b),
			),
		[allExercises],
	)
	const equipmentOptions = React.useMemo(
		() =>
			[
				...new Set(
					allExercises
						.map((ex) => ex.equipment)
						.filter((eq): eq is string => Boolean(eq)),
				),
			].sort((a, b) => a.localeCompare(b)),
		[allExercises],
	)

	const normalizedQuery = query.trim().toLowerCase()
	const filtered = allExercises.filter(
		(ex) =>
			(!normalizedQuery || ex.name.toLowerCase().includes(normalizedQuery)) &&
			(!muscleFilter || ex.primaryMuscle === muscleFilter) &&
			(!equipmentFilter || ex.equipment === equipmentFilter),
	)

	const recentExercises = recentExerciseIds
		.map((recentId) => filtered.find((ex) => ex.id === recentId))
		.filter((ex): ex is ExerciseItem => Boolean(ex))
	const otherExercises = filtered.filter(
		(ex) => !recentExercises.some((recent) => recent.id === ex.id),
	)

	const hasExactMatch = allExercises.some(
		(ex) => ex.name.toLowerCase() === normalizedQuery,
	)
	const showCreateRow = normalizedQuery.length > 0 && !hasExactMatch

	function resetTransientState() {
		setQuery('')
		setCreateName(null)
	}

	function selectExercise(exerciseId: string) {
		onChange(exerciseId)
		setOpen(false)
	}

	function submitCreate(primaryMuscle: string) {
		if (!createName) return
		pendingCreateRef.current = { name: createName, primaryMuscle }
		void createFetcher.submit(
			{ name: createName, primaryMuscle },
			{ method: 'post', action: '/training/exercises' },
		)
	}

	const creating = createFetcher.state !== 'idle'

	return (
		<Popover
			open={open}
			onOpenChange={(nextOpen) => {
				setOpen(nextOpen)
				if (!nextOpen) resetTransientState()
			}}
		>
			<PopoverTrigger
				id={id}
				aria-invalid={invalid}
				onFocus={onFocus}
				onBlur={onBlur}
				className={cn(TRIGGER_CLASS, !selected && 'text-muted-foreground')}
			>
				<span className="flex-1 text-left [overflow-wrap:anywhere]">
					{selected ? selected.name : L.placeholder}
				</span>
				<Icon
					name="selector"
					className="text-muted-foreground pointer-events-none size-4"
					aria-hidden="true"
				/>
			</PopoverTrigger>
			<PopoverContent align="start" className="w-80 p-0">
				{createName == null ? (
					<Command key="exercise-search" shouldFilter={false} loop>
						<CommandInput
							autoFocus
							placeholder={L.searchPlaceholder}
							value={query}
							onValueChange={setQuery}
							aria-label={L.search}
							enterKeyHint="search"
						/>
						{muscleOptions.length > 0 || equipmentOptions.length > 0 ? (
							<div
								role="group"
								aria-label={L.filters}
								className="flex flex-wrap gap-x-1.5 gap-y-2.5 px-2 py-2"
							>
								{muscleOptions.map((muscle) => (
									<FilterChip
										key={muscle}
										label={formatMuscleLabel(muscle)}
										pressed={muscleFilter === muscle}
										onToggle={() =>
											setMuscleFilter((current) =>
												current === muscle ? null : muscle,
											)
										}
									/>
								))}
								{equipmentOptions.map((equipment) => (
									<FilterChip
										key={equipment}
										label={nbEquipmentLabel(equipment)}
										pressed={equipmentFilter === equipment}
										onToggle={() =>
											setEquipmentFilter((current) =>
												current === equipment ? null : equipment,
											)
										}
									/>
								))}
							</div>
						) : null}
						<CommandList>
							{!showCreateRow ? <CommandEmpty>{L.empty}</CommandEmpty> : null}
							{recentExercises.length > 0 ? (
								<CommandGroup heading={L.recent}>
									{recentExercises.map((ex) => (
										<CommandItem
											key={ex.id}
											value={`recent-${ex.id}`}
											data-checked={ex.id === value || undefined}
											onSelect={() => selectExercise(ex.id)}
										>
											<span className="flex-1">{ex.name}</span>
											<span className="text-caption text-muted-foreground font-normal">
												{formatMuscleLabel(ex.primaryMuscle)}
											</span>
										</CommandItem>
									))}
								</CommandGroup>
							) : null}
							{recentExercises.length > 0 && otherExercises.length > 0 ? (
								<CommandSeparator />
							) : null}
							{otherExercises.length > 0 ? (
								<CommandGroup
									heading={recentExercises.length > 0 ? L.all : undefined}
								>
									{otherExercises.map((ex) => (
										<CommandItem
											key={ex.id}
											value={ex.id}
											data-checked={ex.id === value || undefined}
											onSelect={() => selectExercise(ex.id)}
										>
											<span className="flex-1">{ex.name}</span>
											<span className="text-caption text-muted-foreground font-normal">
												{formatMuscleLabel(ex.primaryMuscle)}
											</span>
										</CommandItem>
									))}
								</CommandGroup>
							) : null}
							{showCreateRow ? (
								<CommandGroup forceMount>
									<CommandItem
										value={`create-${normalizedQuery}`}
										forceMount
										onSelect={() => setCreateName(query.trim())}
									>
										<Icon name="plus" aria-hidden="true" />
										<span className="flex-1">{L.create(query.trim())}</span>
									</CommandItem>
								</CommandGroup>
							) : null}
						</CommandList>
					</Command>
				) : (
					<Command key="muscle-pick" loop>
						<div className="text-caption text-muted-foreground px-3 pt-2 font-normal">
							{L.muscleFor(createName)}
						</div>
						<CommandInput
							autoFocus
							placeholder={L.muscleSearchPlaceholder}
							aria-label={L.muscleSearch}
							enterKeyHint="search"
						/>
						<CommandList>
							<CommandEmpty>{L.muscleEmpty}</CommandEmpty>
							<CommandGroup>
								{MUSCLE_GROUPS.map((muscle) => (
									<CommandItem
										key={muscle}
										value={muscle}
										disabled={creating}
										onSelect={() => submitCreate(muscle)}
									>
										{formatMuscleLabel(muscle)}
									</CommandItem>
								))}
							</CommandGroup>
						</CommandList>
						<div className="flex items-center justify-between px-1 py-1">
							<Button
								type="button"
								variant="ghost"
								size="sm"
								onClick={() => setCreateName(null)}
							>
								{L.back}
							</Button>
							{creating ? (
								<span className="text-caption text-muted-foreground px-2 font-normal">
									{L.saving}
								</span>
							) : createFetcher.data?.error ? (
								<span className="text-caption text-destructive px-2">
									{createFetcher.data.error}
								</span>
							) : null}
						</div>
					</Command>
				)}
			</PopoverContent>
		</Popover>
	)
}

/**
 * @vitest-environment jsdom
 *
 * **The runner's tap-to-log grid, driven by real taps** (ADR 0064).
 *
 * Every test below taps a circle and asserts what was **posted**, because the
 * whole claim of this surface is that a tap is a write: no save button, no load
 * field, and nothing on the screen that is a promise about a set rather than a
 * record of one.
 */
import {
	act,
	fireEvent,
	render,
	screen,
	waitFor,
	within,
} from '@testing-library/react'
import { userEvent } from '@testing-library/user-event'
import { createRoutesStub } from 'react-router'
import { afterEach, expect, test, vi } from 'vitest'
import { type PlateInventory } from '#app/utils/strength/plates.ts'
import {
	REST_ADJUST_STEP_SEC,
	REST_AFTER_MADE_SET_SEC,
	REST_AFTER_MISSED_SET_SEC,
	REST_BEFORE_LAST_WARMUP_SEC,
} from '#app/utils/strength/rest.ts'
import { type StrengthLogView } from '#app/utils/strength-log.server.ts'
import { REST_TICK_MS } from './__rest-bar.tsx'
import { type LiftProgress } from './__runner-presenter.ts'
import SetLogRoute from './sessions.$sessionId_.log.tsx'

/**
 * Finish with sets still untapped asks first (owner decision 10). Tests about
 * what Finish leads to answer "marker som ikke gjort"; the question itself is
 * tested on its own below.
 */
async function answerUntapped() {
	const markNotDone = await screen
		.findByRole('button', { name: 'Marker som ikke gjort' }, { timeout: 500 })
		.catch(() => null)
	if (markNotDone) await userEvent.click(markNotDone)
}

type LogRow = StrengthLogView['exercises'][0]['rows'][0]
type LogExercise = StrengthLogView['exercises'][0]

function row(overrides: Partial<LogRow> = {}): LogRow {
	return {
		orderIndex: 0,
		exerciseSetId: 'set-1',
		prescribedReps: 5,
		prescribedDurationSec: null,
		prescribedLoad: { kind: 'absolute' as const, kg: 82.5 },
		resolvedLoad: null,
		warmupRung: null,
		logged: null,
		ghost: null,
		...overrides,
	}
}

/** Five prescribed working sets, the StrongLifts shape. */
function workingSets(count = 5): LogRow[] {
	return Array.from({ length: count }, (_, index) =>
		row({ orderIndex: index, exerciseSetId: `set-${index + 1}` }),
	)
}

function exercise(overrides: Partial<LogExercise> = {}): LogExercise {
	return {
		stepId: 'step-1',
		exerciseId: 'ex-1',
		name: 'Squat',
		restBetweenSetsSec: null,
		unilateral: null,
		loadSemanticsKind: null,
		rows: workingSets(),
		warmupRows: [],
		warmupUnavailable: null,
		plateContext: null,
		...overrides,
	}
}

/** The loader's view, plus what the loader adds to it: which session of the run
 * this is (#480's badge). */
type LoaderView = StrengthLogView & { sessionNumber: number | null }

function view(overrides: Partial<LoaderView> = {}): LoaderView {
	return {
		sessionNumber: null,
		sessionId: 'sess-1',
		sessionTitle: 'Workout A',
		scheduledAt: new Date('2026-08-19T17:00:00Z'),
		status: 'scheduled',
		bodyweightKg: 80,
		exercises: [exercise()],
		hasGymOnFile: false,
		program: null,
		...overrides,
	}
}

function renderLog(
	overrides: Partial<LoaderView> = {},
	actionResult: unknown = { ok: true },
	/** Where each lift of the run stands, which is what the help panel says the
	 * weight in — empty outside a program. */
	liftProgress: LiftProgress[] = [],
) {
	const submitted = vi.fn()
	const App = createRoutesStub([
		{
			path: '/training/sessions/:sessionId/log',
			Component: (props: Record<string, unknown>) => (
				<SetLogRoute {...(props as any)} />
			),
			loader: () => ({ ...view(overrides), liftProgress }),
			action: async ({ request }) => {
				submitted(Object.fromEntries(await request.formData()))
				return actionResult
			},
			HydrateFallback: () => <div>Loading...</div>,
		},
	])
	render(<App initialEntries={['/training/sessions/sess-1/log']} />)
	return { submitted }
}

/** A three-rung ramp: two empty-bar fives, then the rungs up to the work weight. */
function rungs(): LogRow[] {
	return [
		{ orderIndex: 1000, kg: 20, reps: 5 },
		{ orderIndex: 1001, kg: 40, reps: 5 },
		{ orderIndex: 1002, kg: 60, reps: 3 },
	].map((rung) =>
		row({
			orderIndex: rung.orderIndex,
			exerciseSetId: null,
			prescribedReps: rung.reps,
			warmupRung: { targetKg: rung.kg, effectiveKg: rung.kg, plateLine: '' },
		}),
	)
}

/** The chip for rung `n` of the default lift, ticked or not. */
function chip(n: number) {
	return screen.getByLabelText(
		new RegExp(`^Logg(et)? oppvarming ${n} av Squat,`),
	)
}

function chipLabels() {
	return [...document.querySelectorAll('[data-warmup-chip]')].map(
		(node) => node.textContent,
	)
}

/** The circle for set `n` of the default lift. */
function circle(n: number) {
	return screen.getByLabelText(new RegExp(`^Logg(et)? sett ${n} av Squat$`))
}

